#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

use plexify::ui::runner::{self, RunnerOptions};
use plexify::ui::theme;
use plexify::ui::app::{LaunchOptions, PlexifyApp, TOKEN_NAME};
use plexify::{config::Config, logging, paths, secure_store, win::single_instance};
use std::sync::Arc;

/// Raw 64x64 RGBA generated by tools/make_icon.py (no PNG decoder needed at runtime).
fn load_icon() -> egui::IconData {
    let rgba = include_bytes!("../../../assets/icon64.rgba");
    egui::IconData { rgba: rgba.to_vec(), width: 64, height: 64 }
}

fn main() {
    let log_path = logging::init(&paths::log_dir(), cfg!(debug_assertions));
    log::info!("Plexify {} starting (log: {})", env!("CARGO_PKG_VERSION"), log_path.display());

    let Some(_guard) = single_instance::acquire() else {
        log::info!("another instance is running; activating it");
        single_instance::activate_existing();
        return;
    };

    let opts = LaunchOptions::from_args(std::env::args().skip(1));
    if let Some(u) = &opts.plex_tv_url {
        log::info!("using Plex endpoint override {u}");
    }
    let config = Config::load();
    let size = config.window_size.unwrap_or([1180.0, 760.0]);
    let options = RunnerOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title("Plexify")
            .with_app_id("Plexify")
            .with_inner_size(size)
            .with_min_inner_size([760.0, 480.0])
            .with_icon(load_icon())
            .with_drag_and_drop(false),
        background: theme::BG,
    };
    let ctx = egui::Context::default();
    // CJK/emoji titles fall back to an installed system font instead of rendering as boxes.
    ctx.add_font_provider(Arc::new(plexify::ui::fonts::system_provider()));
    if let Err(e) = runner::run(options, ctx, move |ctx, _proxy| {
        let store: Arc<dyn secure_store::SecretStore> = Arc::from(secure_store::default_store(TOKEN_NAME));
        PlexifyApp::new(ctx, config, opts, store)
    }) {
        log::error!("UI terminated with error: {e}");
    }
    log::info!("Plexify exiting");
}
